package com.politeness.ading.conductor.controller.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * Creates a workspace. workspaceId may be generated by the client, for idempotent offline replay.
 * terminalId is the computer the directory lives on; when called with a computer token, the token's value wins.
 */
public record WorkspaceCreateRequest(
        String workspaceId,
        @NotBlank String name,
        @NotBlank String path,
        String terminalId) {
}
